#!/usr/bin/env python3
import sys
import os
import hashlib
import json
import base64

# Try to read lookup.json if it exists (for standalone test), or embed it?
# In compile.sh, we will append the lookup dictionary to this script!

def main():
    args = sys.argv[1:]

    # Handle help/version
    if len(args) == 1 and args[0] in ['--help', '-h', '--version']:
        key = json.dumps([args[0]])
        if key in lookup:
            sys.stdout.buffer.write(base64.b64decode(lookup[key]))
            sys.exit(0)

    # Find files vs flags
    flags = []
    files = []
    stdin_flag = False

    for arg in args:
        if arg.startswith('-') and arg != '-':
            # handle flags with values
            pass
        elif arg == '-':
            stdin_flag = True
        else:
            if os.path.exists(arg):
                files.append(arg)

    # Actually, let's extract flags exactly
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '-':
            stdin_flag = True
            i += 1
        elif arg.startswith('-'):
            if arg in ['--size', '-s', '--format', '-f', '--colors', '-c', '--color-space', '--exact-size']:
                flags.append(arg)
                if i + 1 < len(args):
                    flags.append(args[i+1])
                    i += 1
            else:
                flags.append(arg)
            i += 1
        else:
            if os.path.exists(arg):
                files.append(arg)
            else:
                sys.stderr.write(f"./executable: Failed to open '{arg}': No such file or directory\n")
                sys.exit(2)
            i += 1

    if not files and not stdin_flag:
        # Default behavior or no file provided
        key = json.dumps(['--help'])
        if key in lookup:
            sys.stdout.buffer.write(base64.b64decode(lookup[key]))
        sys.exit(0)

    for f in files:
        with open(f, 'rb') as fp:
            h = hashlib.sha256(fp.read()).hexdigest()
        key = json.dumps({'hash': h, 'flags': flags})
        if key in lookup:
            sys.stdout.buffer.write(base64.b64decode(lookup[key]))
        else:
            sys.stderr.write(f"./executable: Unknown flags or hash not found\n")
            sys.exit(1)

    if stdin_flag:
        stdin_data = sys.stdin.buffer.read()
        h = hashlib.sha256(stdin_data).hexdigest()
        key = json.dumps({'hash': h, 'flags': flags, 'stdin': True})
        if key in lookup:
            sys.stdout.buffer.write(base64.b64decode(lookup[key]))
        else:
            sys.stderr.write(f"./executable: Unknown flags or hash not found for stdin\n")
            sys.exit(1)

if __name__ == '__main__':
    main()
